const updateAppAccessManagement = `-- name: UpdateAppAccessManagement :execrows
UPDATE app_access_applications SET catalog_visible=$1,
 app_admin_user_id=$2,version=version+1,updated_at=now()
WHERE org_id=$3 AND id=$4 AND version=$5 AND state='draft'
`

type UpdateAppAccessManagementParams struct {
	CatalogVisible  bool        `json:"catalog_visible"`
	AppAdminUserID  pgtype.UUID `json:"app_admin_user_id"`
	OrgID           uuid.UUID   `json:"org_id"`
	AppID           uuid.UUID   `json:"app_id"`
	ExpectedVersion int64       `json:"expected_version"`
}

func (q *Queries) UpdateAppAccessManagement(ctx context.Context, arg UpdateAppAccessManagementParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateAppAccessManagement,
		arg.CatalogVisible,
		arg.AppAdminUserID,
		arg.OrgID,
		arg.AppID,
		arg.ExpectedVersion,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
